apiVersion: policy/v1
kind: PodDisruptionBudget
metadata: { name: {nombre}, namespace: {ns} }
spec:
  minAvailable: {disponibles}
  selector: { matchLabels: { app.kubernetes.io/name: {app} } }

strategy:
  canary:
    steps:
      - setWeight: {peso}
      - pause: { duration: {espera} }

kubectl config current-context
kubectl config use-context {contexto}
kubectl config set-context --current --namespace={ns}

kubectl get {tipo}/{nombre} -n {ns} -o jsonpath='{{ruta}}{"\n"}'
kubectl explain {tipo}.{campo}
kubectl diff -f {archivo}

kubectl exec -it -n {ns} {pod} -c {contenedor} -- {comando}
kubectl port-forward -n {ns} svc/{nombre} {local}:{puerto}
kubectl auth can-i {verbo} {tipo} -n {ns}
